"""Practice sets for Form 5 Literature in English: Literary Appreciation Fundamentals and Prescribed Poetry Anthology
(one set per lesson). All passages and poems are invented by KKEVO Academy for practice."""

from .dsl import *  # noqa: F403

COURSE = ("literature-in-english", "form-5")

M1 = "Literary Appreciation Fundamentals"
M2 = "Prescribed Poetry Anthology"

_SEQ = [1, 3, 0, 2, 2, 0, 3, 1, 0, 2, 1, 3, 3, 1, 2, 0]
_N = [0]


def Q(prompt, options, ci, whys, step, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """MC question: `options` as written, `ci` the index of the correct one, `whys` the three explanations of the
    wrong options in order. The correct option is swapped to a rotating position so answers spread over A-D."""
    whys = list(whys)
    assert len(whys) == len(options) - 1, prompt
    chs = []
    k = 0
    for i, text in enumerate(options):
        if i == ci:
            chs.append(C(text, correct=True))
        else:
            chs.append(C(text, why=whys[k]))
            k += 1
    target = _SEQ[_N[0] % len(_SEQ)]
    _N[0] += 1
    chs[ci], chs[target] = chs[target], chs[ci]
    return MC(prompt, chs, steps=[S(t, text=x) for t, x in step], concept=concept, skill=skill, hint=hint,
              feedback=feedback, diagram=diagram, diagram_alt=diagram_alt)


